import java.util.*;

class Solution {
  public int numberOfPoints(List<List<Integer>> nums) {
    int[] difference = new int[102];
    for (List<Integer> car : nums) {
      difference[car.get(0)]++;
      difference[car.get(1) + 1]--;
    }
    int answer = 0, active = 0;
    for (int point = 1; point <= 100; point++) {
      active += difference[point];
      if (active > 0) answer++;
    }
    return answer;
  }
}
